DROP TABLE IF EXISTS `spc_data_bt`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `spc_data_bt` (
  `VsPrimaryKey` varchar(48) NOT NULL,
  `kind` int(11) DEFAULT NULL COMMENT '1: 自主檢查 \n10: QC 巡檢\n11: QC 首件檢\n19: 末件檢 \n-----------------------\n0: all <-- for search\n\n2019/12/06 lkchena\n',
  `tool_id` varchar(12) DEFAULT NULL COMMENT 'length extend to 12 for sintering "before/after" omi -- 2020/03/18 lkchena',
  `part_id` varchar(24) DEFAULT NULL,
  `part_raw` varchar(16) DEFAULT NULL,
  `route_id` varchar(24) NOT NULL DEFAULT '000' COMMENT '2020/04/08 lkchena',
  `mold_id` varchar(16) DEFAULT NULL,
  `recipe_id` varchar(32) DEFAULT NULL,
  `ope_no` varchar(7) NOT NULL COMMENT '2020/03/17 lkchena: for option flow, extend length to 7',
  `ope_name` varchar(36) NOT NULL DEFAULT 'MEAS_STEP',
  `stage_id` varchar(16) NOT NULL DEFAULT 'MEAS_STAGE',
  `stage_name` varchar(36) NOT NULL DEFAULT 'MEAS_STAGE',
  `stage_order` varchar(3) NOT NULL DEFAULT '100',
  `ws_type` varchar(12) NOT NULL DEFAULT '000' COMMENT '2020/04/09 lkchena',
  `ws_func` varchar(24) DEFAULT NULL COMMENT '2020/04/09 lkchena',
  `tool_type` varchar(12) NOT NULL DEFAULT '000' COMMENT '2020/04/08 lkchena',
  `tool_func` varchar(24) DEFAULT NULL COMMENT '2020/04/08 lkchena',
  `idxfield` int(11) NOT NULL,
  `field_name` varchar(24) DEFAULT NULL,
  `field_desc` varchar(64) DEFAULT NULL,
  `mfg_no` varchar(24) NOT NULL,
  `rd_flag` int(11) DEFAULT 0 COMMENT '0: prod 1: test run 2: rd ',
  `time_order` varchar(19) DEFAULT 'NULL',
  `powder_id` varchar(24) DEFAULT NULL,
  `powder_type` varchar(16) DEFAULT NULL,
  `lot_id` varchar(12) DEFAULT NULL,
  `lot_size` int(11) DEFAULT NULL,
  `wafer_id` varchar(12) DEFAULT NULL,
  `result` int(11) DEFAULT 0 COMMENT 'test results: 0:wait test 1:pass -1:ng 2:waive 9:cancel ',
  `ope_cate` varchar(12) DEFAULT NULL,
  `backup` varchar(4) DEFAULT NULL,
  `main_tool` varchar(12) DEFAULT NULL,
  `meas_tool` varchar(12) DEFAULT NULL,
  `user_id` varchar(16) DEFAULT NULL,
  `user_name` varchar(32) DEFAULT NULL,
  `shift_id` varchar(4) DEFAULT NULL,
  `sample` int(11) DEFAULT 5 COMMENT 'spc sample count, related n99 field (old version is use xvalue1) (default: 5)\n2019/12/13 lkchena',
  `filter` int(11) DEFAULT 0 COMMENT 'spc need it, fdc need it ??? 2019/12/17 lkchena\n\nfor customer audit \n0: normal show\n1: hide not show and calculate\n2019/12/17 lkchena',
  `xvalue1` double DEFAULT 5 COMMENT 'to be sample count of spc, default 5\n-- 2019/12/04 lkchena',
  `xvalue2` double DEFAULT NULL,
  `xvalue3` double DEFAULT 0 COMMENT 'to be today measure amount for manual check( chin-chih )\n2019/12/13 lkchena',
  `n01` double DEFAULT NULL,
  `n02` double DEFAULT NULL,
  `n03` double DEFAULT NULL,
  `n04` double DEFAULT NULL,
  `n05` double DEFAULT NULL,
  `n06` double DEFAULT NULL,
  `n07` double DEFAULT NULL,
  `n08` double DEFAULT NULL,
  `n09` double DEFAULT NULL,
  `n10` double DEFAULT NULL,
  `n11` double DEFAULT NULL,
  `n12` double DEFAULT NULL,
  `n13` double DEFAULT NULL,
  `n14` double DEFAULT NULL,
  `n15` double DEFAULT NULL,
  `n16` double DEFAULT NULL,
  `claim_time` varchar(19) DEFAULT 'NULL',
  `rec_user` varchar(16) DEFAULT NULL,
  `rec_time` varchar(19) DEFAULT 'NULL',
  `node_id` varchar(16) DEFAULT NULL,
  `node_time` timestamp(6) NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`VsPrimaryKey`),
  KEY `idx1` (`tool_id`,`field_name`,`time_order`),
  KEY `idx2` (`mfg_no`,`time_order`,`ope_no`,`field_name`,`kind`),
  KEY `idx3_stage` (`part_id`,`stage_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
